<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Foundry Nine — a three.js tactical FPS</title>
<style>
  /* Look plan: cold steel, warm ember. One accent, two team colours. */
  :root {
    --canvas: #101418;
    --surface: #1c2126;
    --hairline: #3a434c;
    --ink: #ece7db;
    --muted: #8b949c;
    --accent: #ff7a1a;
    --vanguard: #4db2ff;
    --ember: #ff5340;
    --site: #ffc53d;
    --radius-panel: 4px;
    --radius-control: 8px;
    --font-ui: system-ui, -apple-system, 'Segoe UI', sans-serif;
    --font-readout: ui-monospace, 'SF Mono', Menlo, monospace;
  }
  * { box-sizing: border-box; }
  html, body {
    margin: 0;
    height: 100%;
    overflow: hidden;
    background: var(--canvas);
    color: var(--ink);
    font-family: var(--font-ui);
  }
  #game, #game canvas { position: fixed; inset: 0; display: block; }
  #hud { position: fixed; inset: 0; pointer-events: none; }

  #crosshair { position: fixed; left: 50%; top: 50%; width: 22px; height: 22px; transform: translate(-50%, -50%); --gap: 4px; }
  #crosshair i { position: absolute; background: var(--ink); opacity: .9; }
  #crosshair i:nth-child(1) { left: 10px; top: calc(-1 * var(--gap)); width: 2px; height: 7px; }
  #crosshair i:nth-child(2) { left: 10px; bottom: calc(-1 * var(--gap)); width: 2px; height: 7px; }
  #crosshair i:nth-child(3) { top: 10px; left: calc(-1 * var(--gap)); height: 2px; width: 7px; }
  #crosshair i:nth-child(4) { top: 10px; right: calc(-1 * var(--gap)); height: 2px; width: 7px; }

  #hitmarker { position: fixed; left: 50%; top: 50%; width: 26px; height: 26px; transform: translate(-50%, -50%) rotate(45deg); opacity: 0; transition: opacity 90ms linear; }
  #hitmarker.on { opacity: 1; }
  #hitmarker.kill i { background: var(--ember); }
  #hitmarker i { position: absolute; background: var(--accent); }
  #hitmarker i:nth-child(1) { left: 12px; top: 0; width: 2px; height: 8px; }
  #hitmarker i:nth-child(2) { left: 12px; bottom: 0; width: 2px; height: 8px; }
  #hitmarker i:nth-child(3) { top: 12px; left: 0; height: 2px; width: 8px; }
  #hitmarker i:nth-child(4) { top: 12px; right: 0; height: 2px; width: 8px; }

  #topbar {
    position: fixed; top: 18px; left: 50%; transform: translateX(-50%);
    display: flex; flex-direction: column; align-items: center; gap: 4px;
    font-family: var(--font-readout);
  }
  #timer-row { display: flex; align-items: center; gap: 14px; font-size: 20px; }
  #timer-value { min-width: 64px; text-align: center; font-size: 24px; }
  #timer-value.bomb { color: var(--ember); }
  #score-vanguard { color: var(--vanguard); font-weight: 700; }
  #score-ember { color: var(--ember); font-weight: 700; }
  #round-value { font-size: 11px; letter-spacing: .18em; color: var(--muted); }
  #bomb-status { font-size: 12px; color: var(--site); min-height: 15px; }

  #teams {
    position: fixed; top: 18px; left: 28px;
    font-family: var(--font-readout); font-size: 13px; line-height: 1.9; color: var(--muted);
  }
  #alive-vanguard { color: var(--vanguard); letter-spacing: 2px; }
  #alive-ember { color: var(--ember); letter-spacing: 2px; }

  #killfeed {
    position: fixed; top: 18px; right: 28px; width: 320px;
    display: flex; flex-direction: column; gap: 6px; align-items: flex-end;
    font-size: 13px; color: var(--muted);
  }
  .feed-line { background: color-mix(in srgb, var(--surface) 82%, transparent); padding: 5px 9px; border-radius: var(--radius-panel); transition: opacity 600ms linear; }
  .feed-line.good { color: var(--ink); border-left: 3px solid var(--vanguard); }
  .feed-line.fade { opacity: 0; }

  #banner {
    position: fixed; left: 50%; top: 30%; transform: translate(-50%, -50%);
    font-size: 30px; font-weight: 600; letter-spacing: -0.02em; text-align: center;
    text-shadow: 0 2px 12px rgba(0,0,0,.8); opacity: 0; transition: opacity 200ms linear;
    max-width: 80vw;
  }
  #banner.on { opacity: 1; }

  #plant-bar {
    position: fixed; left: 50%; top: 58%; transform: translateX(-50%);
    width: 220px; height: 8px; background: var(--hairline); border-radius: 4px; overflow: hidden;
  }
  #plant-fill { height: 100%; width: 0%; background: var(--site); }
  #plant-bar[hidden] { display: none; }

  #health {
    position: fixed; left: 32px; bottom: 24px;
    font-family: var(--font-readout); line-height: 1.1;
  }
  #health-value { font-size: 56px; }
  #health.low #health-value { color: var(--ember); }
  #health .label { font-size: 12px; color: var(--muted); letter-spacing: .14em; }
  #armor-row { font-size: 14px; color: var(--vanguard); margin-top: 4px; }

  #ammo {
    position: fixed; right: 32px; bottom: 24px; text-align: right;
    font-family: var(--font-readout); line-height: 1.15;
  }
  #ammo.empty #ammo-mag { color: var(--accent); }
  #ammo-mag { font-size: 56px; letter-spacing: -0.03em; }
  #ammo-reserve { font-size: 16px; color: var(--muted); }
  #weapon-name { font-size: 13px; color: var(--muted); letter-spacing: .08em; }
  #grenade-count { font-size: 14px; color: var(--accent); margin-top: 2px; min-height: 17px; }
  #money-value { font-size: 20px; color: var(--site); margin-top: 6px; }

  .overlay {
    position: fixed; inset: 0; display: grid; place-items: center; padding: 24px;
    background: color-mix(in srgb, var(--canvas) 86%, transparent);
    pointer-events: auto;
  }
  .overlay[hidden] { display: none; }
  .panel {
    width: min(460px, 100%); padding: 32px;
    background: var(--surface); border: 1px solid var(--hairline); border-radius: var(--radius-panel);
  }
  .panel h1 { margin: 0 0 8px; font-size: 32px; line-height: 1.15; font-weight: 600; letter-spacing: -0.02em; }
  .panel h1 .nine { color: var(--accent); }
  .panel p { margin: 0 0 24px; max-width: 46ch; font-size: 16px; line-height: 1.5; color: var(--muted); }
  #play {
    font: inherit; font-weight: 600; padding: 12px 16px; white-space: nowrap;
    border: 1px solid var(--accent); border-radius: var(--radius-control);
    background: var(--accent); color: var(--canvas); cursor: pointer;
  }
  #play:hover { background: var(--ink); border-color: var(--ink); }
  #play:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
  .keys { margin: 24px 0 0; padding: 0; list-style: none; display: grid; gap: 8px; font-size: 14px; color: var(--muted); }
  .keys li { display: flex; align-items: center; gap: 8px; }
  .keys kbd {
    min-width: 24px; padding: 2px 6px; border: 1px solid var(--hairline);
    border-radius: var(--radius-panel); font-family: var(--font-readout); font-size: 12px; color: var(--ink); text-align: center;
  }

  #buy-menu {
    position: fixed; inset: 0; display: grid; place-items: center; padding: 24px;
    background: color-mix(in srgb, var(--canvas) 70%, transparent);
    pointer-events: auto;
  }
  #buy-menu[hidden] { display: none; }
  .buy-panel {
    width: min(480px, 100%); padding: 28px;
    background: var(--surface); border: 1px solid var(--hairline); border-radius: var(--radius-panel);
  }
  .buy-panel h2 { margin: 0 0 4px; font-size: 22px; }
  .buy-panel .buy-sub { margin: 0 0 18px; font-size: 14px; color: var(--muted); }
  #buy-money { font-family: var(--font-readout); font-size: 20px; color: var(--site); margin-bottom: 16px; }
  #buy-grid { display: grid; gap: 10px; }
  .buy-item {
    display: grid; grid-template-columns: 1fr auto; gap: 2px 12px; text-align: left;
    padding: 12px 14px; background: var(--canvas); color: var(--ink);
    border: 1px solid var(--hairline); border-radius: var(--radius-control); cursor: pointer; font: inherit;
  }
  .buy-item:hover:not(:disabled) { border-color: var(--accent); }
  .buy-item:disabled { opacity: .45; cursor: default; }
  .buy-item.owned { border-color: var(--vanguard); }
  .buy-item b { font-size: 15px; }
  .buy-item span { grid-column: 1; font-size: 13px; color: var(--muted); }
  .buy-item em { grid-row: 1 / span 2; grid-column: 2; align-self: center; font-style: normal; font-family: var(--font-readout); color: var(--site); }
  #buy-close {
    margin-top: 16px; width: 100%; padding: 11px; font: inherit; font-weight: 600;
    background: var(--accent); color: var(--canvas); border: 1px solid var(--accent);
    border-radius: var(--radius-control); cursor: pointer;
  }
  #buy-close:hover { background: var(--ink); border-color: var(--ink); }

  @media (prefers-reduced-motion: reduce) {
    #hitmarker, #banner, .feed-line { transition-duration: 0.01ms; }
  }
</style>
</head>
