// Procedural sound: no audio assets, everything is synthesised with WebAudio.
// Gunshots are filtered noise bursts, hits are short pings, the bomb is a beeper,
// the round end is two low tones. The context starts on the first user gesture.
export function createAudio() {
  let ctx = null;
  let master = null;

  function ensure() {
    if (ctx) return true;
    try {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return false;
      ctx = new AC();
      master = ctx.createGain();
      master.gain.value = 0.35;
      master.connect(ctx.destination);
      return true;
    } catch {
      return false;
    }
  }

  function noiseBurst(duration, filterFreq, gainValue, type = 'lowpass') {
    if (!ensure()) return;
    const length = Math.max(1, Math.floor(ctx.sampleRate * duration));
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i += 1) data[i] = (Math.random() * 2 - 1) * (1 - i / length);
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = filterFreq;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(gainValue, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
    source.connect(filter);
    filter.connect(gain);
    gain.connect(master);
    source.start();
  }

  function tone(freq, duration, gainValue, type = 'sine', slideTo = 0) {
    if (!ensure()) return;
    const osc = ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, ctx.currentTime);
    if (slideTo) osc.frequency.exponentialRampToValueAtTime(slideTo, ctx.currentTime + duration);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(gainValue, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
    osc.connect(gain);
    gain.connect(master);
    osc.start();
    osc.stop(ctx.currentTime + duration + 0.02);
  }

  return {
    unlock() { ensure(); if (ctx && ctx.state === 'suspended') ctx.resume(); },
    shot() { noiseBurst(0.09, 1400, 0.5); tone(180, 0.07, 0.25, 'square', 70); },
    enemyShot(distance) {
      const g = Math.max(0.06, 0.3 - distance * 0.004);
      noiseBurst(0.08, 1100, g);
    },
    dryClick() { tone(1200, 0.04, 0.12, 'square'); },
    reload() { tone(500, 0.05, 0.12, 'square'); tone(700, 0.05, 0.12, 'square'); },
    hit() { tone(1900, 0.06, 0.18, 'sine'); },
    kill() { tone(1900, 0.06, 0.18, 'sine'); tone(2400, 0.09, 0.18, 'sine'); },
    hurt() { tone(220, 0.12, 0.25, 'sawtooth', 120); },
    plantBeep() { tone(1100, 0.09, 0.2, 'square'); },
    defuseBeep() { tone(900, 0.09, 0.2, 'square'); },
    explosion() { noiseBurst(0.7, 320, 0.9); tone(70, 0.5, 0.5, 'sine', 35); },
    roundWin() { tone(520, 0.14, 0.22, 'sine'); setTimeout(() => tone(780, 0.22, 0.22, 'sine'), 140); },
    roundLose() { tone(330, 0.16, 0.22, 'sine'); setTimeout(() => tone(220, 0.26, 0.22, 'sine'), 160); },
    buy() { tone(980, 0.06, 0.15, 'sine'); tone(1320, 0.08, 0.15, 'sine'); },
  };
}
