import { WEAPONS, GRENADE_PRICE, ARMOR_PRICE } from './weapons.js';

const COPY = {
  start: {
    title: 'FOUNDRY NINE',
    copy: 'Vanguard attacks, Ember defends. Plant the bomb on site A or B — or eliminate the whole Ember team. First to 5 rounds takes the match.',
